31	void StorageSystemDatabases::fillData(MutableColumns & res_columns, ContextPtr context, const SelectQueryInfo &) const
32	{
33	    const auto access = context->getAccess();
34	    const bool check_access_for_databases = !access->isGranted(AccessType::SHOW_DATABASES);
35	
36	    const auto databases = DatabaseCatalog::instance().getDatabases();
37	    for (const auto & [database_name, database] : databases)
38	    {
39	        if (check_access_for_databases && !access->isGranted(AccessType::SHOW_DATABASES, database_name))
40	            continue;
41	
42	        if (database_name == DatabaseCatalog::TEMPORARY_DATABASE)
43	            continue; /// We don't want to show the internal database for temporary tables in system.databases
44	
45	        res_columns[0]->insert(database_name);
46	        res_columns[1]->insert(database->getEngineName());
47	        res_columns[2]->insert(context->getPath() + database->getDataPath());
48	        res_columns[3]->insert(database->getMetadataPath());
49	        res_columns[4]->insert(database->getUUID());
50	        res_columns[5]->insert(database->getDatabaseComment());
51	   }
52	}
53	
54	}
